{"command":"cd /Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure && for f in .skilled/skills/sk-design/sk-design-fundamentals/README.md .skilled/skills/sk-design/sk-design-fundamentals/ROUTER.md .skilled/skills/sk-design/sk-design-fundamentals/SKILL.md .skilled/skills/sk-design/sk-design-fundamentals/assets/token-starter-set.md .skilled/skills/sk-design/sk-design-fundamentals/references/*.md; do echo "=== $f"; JEV_FEATURES=0 python3 -B .skilled/skills/sk-doc/scripts/validate_document.py "$f" --json 2>&1 | python3 -c 'import json,sys
d=sys.stdin.read()
try:
    j=json.loads(d)
except Exception:
    print(d[:2000]); raise SystemExit
print(json.dumps([w for w in j.get("warnings",[]) if str(w.get("code","")).startswith("render_")], indent=0))
'; done"}
